const templateFeaturesForTemplates = `-- name: TemplateFeaturesForTemplates :many
SELECT m.template_id, f.id, f.name, f.value FROM template_feature_map m
JOIN template_feature f ON f.id = m.feature_id
WHERE m.template_id = ANY($1::uuid[])
ORDER BY f.name
`

type TemplateFeaturesForTemplatesRow struct {
	TemplateID uuid.UUID `json:"template_id"`
	ID         uuid.UUID `json:"id"`
	Name       string    `json:"name"`
	Value      *string   `json:"value"`
}

func (q *Queries) TemplateFeaturesForTemplates(ctx context.Context, templateIds []uuid.UUID) ([]TemplateFeaturesForTemplatesRow, error) {
	rows, err := q.db.Query(ctx, templateFeaturesForTemplates, templateIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TemplateFeaturesForTemplatesRow{}
	for rows.Next() {
		var i TemplateFeaturesForTemplatesRow
		if err := rows.Scan(
			&i.TemplateID,
			&i.ID,
			&i.Name,
			&i.Value,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

