const templateListPublic = `-- name: TemplateListPublic :many
SELECT DISTINCT t.id, t.author_id, t.project_id, t.name, t.slug, t.image, t.video, t.spec, t.short_description, t.description, t.original_price, t.discount, t.discount_type, t.views, t.version, t.is_verify, t.demo_url, t.required_envs, t.created_at, t.updated_at FROM template t
WHERE t.is_verify = TRUE
  AND ($1::uuid IS NULL
       OR EXISTS (SELECT 1 FROM template_category_map m WHERE m.template_id = t.id AND m.category_id = $1))
  AND ($2::uuid IS NULL
       OR EXISTS (SELECT 1 FROM template_feature_map m WHERE m.template_id = t.id AND m.feature_id = $2))
  AND ($3::numeric IS NULL OR t.original_price >= $3)
  AND ($4::numeric IS NULL OR t.original_price <= $4)
  AND ($5::text[] IS NULL OR EXISTS (
        SELECT 1 FROM unnest($5::text[]) kw
        WHERE t.name ILIKE '%' || kw || '%'
           OR t.description ILIKE '%' || kw || '%'
           OR t.short_description ILIKE '%' || kw || '%'
           OR EXISTS (SELECT 1 FROM template_category_map cm JOIN template_category c ON c.id = cm.category_id
                      WHERE cm.template_id = t.id AND c.name ILIKE '%' || kw || '%')
           OR EXISTS (SELECT 1 FROM template_feature_map fm JOIN template_feature f ON f.id = fm.feature_id
                      WHERE fm.template_id = t.id AND f.name ILIKE '%' || kw || '%')
      ))
ORDER BY t.created_at DESC
LIMIT $7 OFFSET $6
`

type TemplateListPublicParams struct {
	CategoryID *uuid.UUID     `json:"category_id"`
	FeatureID  *uuid.UUID     `json:"feature_id"`
	MinPrice   pgtype.Numeric `json:"min_price"`
	MaxPrice   pgtype.Numeric `json:"max_price"`
	Keywords   []string       `json:"keywords"`
	Offset     int32          `json:"offset"`
	Limit      int32          `json:"limit"`
}

// AI-friendly smart search: OR across name/description/short_description and, via the
// EXISTS subqueries, category/feature names (mirrors filters/template.py::filter_search,
// one keyword is enough to match - not all of them).
func (q *Queries) TemplateListPublic(ctx context.Context, arg TemplateListPublicParams) ([]Template, error) {
	rows, err := q.db.Query(ctx, templateListPublic,
		arg.CategoryID,
		arg.FeatureID,
		arg.MinPrice,
		arg.MaxPrice,
		arg.Keywords,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Template{}
	for rows.Next() {
		var i Template
		if err := rows.Scan(
			&i.ID,
			&i.AuthorID,
			&i.ProjectID,
			&i.Name,
			&i.Slug,
			&i.Image,
			&i.Video,
			&i.Spec,
			&i.ShortDescription,
			&i.Description,
			&i.OriginalPrice,
			&i.Discount,
			&i.DiscountType,
			&i.Views,
			&i.Version,
			&i.IsVerify,
			&i.DemoUrl,
			&i.RequiredEnvs,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

