const templateSubmissionCategoriesFor = `-- name: TemplateSubmissionCategoriesFor :many
SELECT m.submission_id, c.id, c.name FROM template_submission_category_map m
JOIN template_category c ON c.id = m.category_id
WHERE m.submission_id = ANY($1::uuid[])
ORDER BY c.name
`

type TemplateSubmissionCategoriesForRow struct {
	SubmissionID uuid.UUID `json:"submission_id"`
	ID           uuid.UUID `json:"id"`
	Name         string    `json:"name"`
}

func (q *Queries) TemplateSubmissionCategoriesFor(ctx context.Context, submissionIds []uuid.UUID) ([]TemplateSubmissionCategoriesForRow, error) {
	rows, err := q.db.Query(ctx, templateSubmissionCategoriesFor, submissionIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TemplateSubmissionCategoriesForRow{}
	for rows.Next() {
		var i TemplateSubmissionCategoriesForRow
		if err := rows.Scan(&i.SubmissionID, &i.ID, &i.Name); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

