const templateUpdateSubmission = `-- name: TemplateUpdateSubmission :one
UPDATE template_submission_request
SET name              = COALESCE($1, name),
    short_description = COALESCE($2, short_description),
    description       = COALESCE($3, description),
    image             = COALESCE($4, image),
    video             = COALESCE($5, video),
    demo_url          = COALESCE($6, demo_url),
    original_price    = COALESCE($7, original_price),
    required_envs     = COALESCE($8, required_envs),
    updated_at        = NOW()
WHERE id = $9 AND user_id = $10 AND status = 'pending'
RETURNING id, user_id, project_id, name, short_description, description, image, video, demo_url, original_price, status, rejection_reason, template_id, reviewed_by, reviewed_at, required_envs, created_at, updated_at
`

